(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.009+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.016+t*0.28)*10 + Math.cos((x-y)*0.011-t*0.12)*7;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+t*0.4)*10 + Math.cos(sy*0.02-t*0.35)*7;
  const w2y = Math.cos(sy*0.022+t*0.45)*9 + Math.sin(sx*0.019+t*0.38)*6;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*55, 0.085, 1.8, 1.05]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((wx-sX)**2 + (wy-sY)**2);
    const df = d / (180 + Math.sin(t*0.2+sX*0.01)*40);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    hS += Math.sin(d*f*0.5 - t*sp*0.3 + 2.8) * w * 0.5;
  }
  const nw = src.reduce((a,s) => a+s[4], 0);
  const act = aS/nw, inh = iS/nw, hMod = hS/nw;
  const bg1 = (Math.sin(wx*0.04+wy*0.025+t*0.8) + Math.sin(wx*0.03-wy*0.04+t*1.1))/2;
  const bg2 = Math.sin((wx+wy)*0.12+t*2.5)*0.2 + Math.sin((wx-wy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(wx*0.07-wy*0.05+t*1.8)*0.15 + Math.sin(wy*0.06+wx*0.03-t*1.4)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((wx-cx)**2 + (wy-cy)**2), ang = Math.atan2(wy-cy, wx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = Math.sin(dist*0.08-ang*2+t*0.9)*0.2 + Math.sin(dist*0.03+ang*5-t*1.8)*0.15;
  const spiral = sp1 + sp2;
  const turb = Math.sin(wx*0.15+Math.sin(wy*0.12+t*0.5)*2+t)*0.15 + Math.cos(wy*0.13+Math.cos(wx*0.11-t*0.4)*1.8)*0.12;
  const rd1 = act - inh*0.7 + bg*0.25 + spiral*0.6 + turb;
  const rd2 = Math.sin(rd1*2.5)*0.4 + Math.cos(rd1*1.8+0.7)*0.3;
  const reaction = Math.tanh((rd1 + rd2)*1.8);
  const cell1 = Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15) + Math.sin((wx+wy)*0.1+t)*0.5)*1.5);
  const cell2 = Math.sin(wx*0.22+wy*0.08-t*0.7)*Math.cos(wy*0.2-wx*0.06+t*0.5)*0.4;
  const cell = (cell1 + cell2)*0.15;
  const ridge = Math.abs(Math.sin(dist*0.06 - ang*2 - t*0.8))*0.15;
  const blend = reaction*0.65 + cell*0.2 + ridge*0.15;
  const v = blend*0.5+0.5;
  const hShift = Math.tanh(hMod)*0.12;
  const pal = [[5,10,45],[10,45,85],[15,85,120],[20,140,135],[45,175,130],[140,195,90],[210,185,60],[230,140,55],[215,90,60],[180,50,70],[120,25,55],[60,15,45],[5,10,45]];
  const shifted = v + hShift;
  const idx = Math.max(0, Math.min(shifted, 0.999))*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.82 + Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.72 ? 1.12 + (Math.abs(reaction)-0.72)*0.5 : 1.0;
  const glow = Math.max(0, 1-dist/320)*0.08*Math.sin(t*0.8)*0.5;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge + glow*55)|0)
  ];
}
